"""Schema-driven (unaligned) PER encoder for ASN.1 dissectors generated by
asn2wrs (here: packet-ilp.c).  The type tree is read from the generated
dissector: the per_sequence_t / per_choice_t tables and the bodies of the
dissect_<proto>_<Type>() functions.  CHOICE alternatives are visited round
robin, optional elements and extension additions are included
pseudo randomly.  Everything is synthetic; all values are made up."""
import re
import random


class Bits:
    def __init__(self):
        self.b = []

    def put(self, v, n):
        for i in range(n - 1, -1, -1):
            self.b.append((v >> i) & 1)

    def octets(self, data):
        for c in data:
            self.put(c, 8)

    def bits(self, other):
        self.b += other.b

    def tobytes(self):
        b = self.b + [0] * (-len(self.b) % 8)
        return bytes(int(''.join(map(str, b[i:i + 8])), 2) for i in range(0, len(b), 8))

    def __len__(self):
        return len(self.b)


def nbits(rng_size):
    return (rng_size - 1).bit_length() if rng_size > 1 else 0


DEFINES = {}


def num(s):
    s = s.strip()
    s = re.sub(r'^U?INT64_C\((.*)\)$', r'\1', s)
    if s in DEFINES:
        return DEFINES[s]
    if s == 'INT32_MIN':
        return -2147483648
    if s == 'NO_BOUND':
        return None
    s = re.sub(r'(?<=[0-9a-fA-Fx])(ULL|LL|UL|U|L)$', '', s)
    try:
        return int(s, 0)
    except ValueError:
        return None


class PerSchema:
    def __init__(self, path, prefix, seed=1):
        # path may be a list of files (merged), prefix a regex alternation
        # such as 'lppe?'
        paths = path if isinstance(path, (list, tuple)) else [path]
        srcs = []
        for n, p in enumerate(paths):
            t = open(p).read()
            if n:
                # the static table names of the merged files may clash
                names = set(re.findall(r'static const per_(?:sequence|choice)_t (\w+)\[', t))
                t = re.sub(r'\b(%s)\b' % '|'.join(sorted(names, key=len, reverse=True)), r'\1__m%d' % n, t)
            srcs.append(t)
        self.src = '\n'.join(srcs)
        for n, v in re.findall(r'#define (\w+)\s+(-?\d+)\s*$', self.src, re.M):
            DEFINES[n] = int(v)
        self.prefix = prefix
        self.rng = random.Random(seed)
        self.rr = {}
        self.tables = {}
        self.funcs = {}
        self.hooks = {}
        self.trace = None
        self.visit = None        # a set: keys of what an encoding touched
        self.tab_ext = set()      # empty extensible SEQUENCEs
        self.fixed = {}
        self.depth = 0
        self.maxdepth = 30
        self.ext_prob = 0.2
        self.opt_skip = 0.35
        self.avoid_re = None      # regex on the hf name of CHOICE alternatives to avoid (95%)
        self.never_re = None      # regex on the function name of OPTIONAL elements that are never present
        self.force_re = None      # regex on the function name of OPTIONAL elements that are always present
        self._parse()
        self._scores()

    def _parse(self):
        s = self.src
        for m in re.finditer(r'static const per_(sequence|choice)_t (\w+)\[\d*\] = \{(.*?)\n\};', s, re.S):
            kind, name, body = m.groups()
            ents = []
            if kind == 'sequence':
                for e in re.finditer(r'\{\s*&(\w+)\s*,\s*(ASN1_\w+)\s*,\s*(ASN1_\w+)\s*,\s*(\w+)\s*\}', body):
                    hf, ext, opt, func = e.groups()
                    ents.append(dict(hf=hf, ext=ext, opt=opt == 'ASN1_OPTIONAL', func=func))
            else:
                for e in re.finditer(r'\{\s*(\d+)\s*,\s*&(\w+)\s*,\s*(ASN1_\w+)\s*,\s*(\w+)\s*\}', body):
                    val, hf, ext, func = e.groups()
                    ents.append(dict(val=int(val), hf=hf, ext=ext, func=func))
            self.tables[name] = (kind, ents)
            if re.search(r'\{\s*NULL\s*,\s*ASN1_EXTENSION_ROOT', body):
                self.tab_ext.add(name)
        pat = r'(?:^|\n)(?:static )?(?:unsigned|uint32_t)\n(dissect_(?:%s)_\w+)\(tvbuff_t \*tvb.*?\) \{\n(.*?)\n\}\n' % self.prefix
        for m in re.finditer(pat, s, re.S):
            name, body = m.groups()
            self.funcs[name] = self._kind(body)

    def _args(self, call):
        i = call.index('(')
        a, depth, cur, instr = [], 0, '', False
        for ch in call[i + 1:]:
            if ch == '"':
                instr = not instr
            if not instr:
                if ch == '(':
                    depth += 1
                if ch == ')':
                    if depth == 0:
                        break
                    depth -= 1
                if ch == ',' and depth == 0:
                    a.append(cur.strip()); cur = ''
                    continue
            cur += ch
        a.append(cur.strip())
        return a

    def _kind(self, body):
        m = re.search(r'(dissect_per_\w+|dissect_(?:%s)_\w+)\((.*?)\);' % self.prefix, body, re.S)
        if not m:
            return ('any',)
        fn = m.group(1)
        a = self._args(fn + '(' + m.group(2) + ')')
        if re.match(r'dissect_(?:%s)_' % self.prefix, fn):
            return ('alias', fn)
        if fn == 'dissect_per_sequence':
            return ('seq', a[6])
        if fn == 'dissect_per_sequence_eag':
            return ('seq', a[4])
        if fn == 'dissect_per_null':
            return ('null',)
        if fn == 'dissect_per_constrained_integer_64b':
            return ('int', num(a[5]), num(a[6]), a[8] == 'true')
        if fn == 'dissect_per_choice':
            return ('choice', a[6])
        if fn == 'dissect_per_constrained_sequence_of':
            return ('seqof', a[6], num(a[7]), num(a[8]), a[9] == 'true')
        if fn == 'dissect_per_sequence_of':
            return ('seqof', a[6], 0, None, False)
        if fn == 'dissect_per_constrained_integer':
            return ('int', num(a[5]), num(a[6]), a[8] == 'true')
        if fn == 'dissect_per_enumerated':
            return ('enum', num(a[5]), a[7] == 'true')
        if fn == 'dissect_per_boolean':
            return ('bool',)
        if fn == 'dissect_per_bit_string':
            return ('bits', num(a[5]), num(a[6]), a[7] == 'true')
        if fn == 'dissect_per_octet_string':
            return ('octets', num(a[5]), num(a[6]), a[7] == 'true')
        if fn in ('dissect_per_IA5String', 'dissect_per_VisibleString'):
            return ('str', 7, None, num(a[5]), num(a[6]), a[7] == 'true')
        if fn == 'dissect_per_restricted_character_string':
            alpha = a[8].strip('"')
            return ('str', nbits(num(a[9])), alpha, num(a[5]), num(a[6]), a[7] == 'true')
        return ('any',)

    def _scores(self):
        INF = 10 ** 9
        sc = {f: INF for f in self.funcs}
        for _ in range(80):
            ch = False
            for f, k in self.funcs.items():
                t = k[0]
                if t == 'seq':
                    ents = self.tables.get(k[1], ('', []))[1]
                    v = 1 + sum(sc.get(e['func'], 1) for e in ents if not e['opt'] and e['ext'] != 'ASN1_NOT_EXTENSION_ROOT')
                elif t == 'seqof':
                    ents = self.tables.get(k[1], ('', []))[1]
                    v = 1 + ((sc.get(ents[0]['func'], 1) if ents and (k[2] or 0) > 0 else 0))
                elif t == 'choice':
                    ents = self.tables.get(k[1], ('', []))[1]
                    v = 1 + min([sc.get(e['func'], 1) for e in ents if e['ext'] != 'ASN1_NOT_EXTENSION_ROOT'] or [0])
                elif t == 'alias':
                    v = sc.get(k[1], 1)
                else:
                    v = 1
                v = min(v, INF)
                if v < sc[f]:
                    sc[f] = v; ch = True
            if not ch:
                break
        self.score = sc

    def resolve(self, func):
        while func in self.funcs and self.funcs[func][0] == 'alias':
            func = self.funcs[func][1]
        return func

    def pick(self, key, n):
        i = self.rr.get(key, self.rng.randrange(n))
        self.rr[key] = (i + 1) % n
        return i

    # ---- helpers
    def length_det(self, w, n, lo, hi):
        """length determinant for n items with size bounds lo..hi"""
        if lo is not None and hi is not None and lo == hi:
            return
        if hi is not None and hi < 65536:
            lo = lo or 0
            w.put(n - lo, nbits(hi - lo + 1))
        else:
            self.uncon_len(w, n)

    def uncon_len(self, w, n):
        if n < 128:
            w.put(n, 8)
        else:
            assert n < 16384
            w.put(0x8000 | n, 16)

    def open_type(self, w, inner):
        b = inner.tobytes() or b'\x00'
        self.uncon_len(w, len(b))
        for x in b:
            w.put(x, 8)

    def _present(self, e, deep):
        if not e['opt']:
            return True
        if self.never_re and re.search(self.never_re, e['func']):
            return False
        if self.force_re and re.search(self.force_re, e['func']):
            return True
        return not (deep or self.rng.random() < self.opt_skip)

    def _choice_enc(self, w, root, adds, alts, i, extensible):
        if self.visit is not None:
            self.visit.add(('alt', (root + adds)[i]['hf']))
        if extensible:
            w.put(1 if i >= len(root) else 0, 1)
        if i < len(root):
            w.put(i, nbits(len(root)))
            self._enc(root[i]['func'], w)
        else:
            j = i - len(root)
            w.put(0, 1); w.put(j, 6)       # normally small non-negative whole number
            inner = Bits()
            self._enc(adds[j]['func'], inner)
            self.open_type(w, inner)

    # ---- encoding
    def enc(self, func, w=None):
        top = w is None
        w = Bits() if top else w
        self._enc(func, w)
        return w

    def _enc(self, func, w):
        if func in self.hooks:
            return self.hooks[func](self, w)
        return self._enc_plain(func, w)

    def _enc_plain(self, func, w):
        k = self.funcs.get(func, ('any',))
        t = k[0]
        rng = self.rng
        if self.visit is not None:
            self.visit.add(func)
        if self.trace is not None:
            self.trace.append('%s%s %s @%d' % ('  ' * self.depth, func, t, len(w.b)))
        deep = self.depth > self.maxdepth
        self.depth += 1
        try:
            if t == 'alias':
                return self._enc(k[1], w)
            if t == 'seq':
                ents = self.tables[k[1]][1]
                extensible = any(e['ext'] != 'ASN1_NO_EXTENSIONS' for e in ents) or k[1] in self.tab_ext
                root = [e for e in ents if e['ext'] != 'ASN1_NOT_EXTENSION_ROOT']
                adds = [e for e in ents if e['ext'] == 'ASN1_NOT_EXTENSION_ROOT']
                use_ext = bool(adds) and not deep and rng.random() < self.ext_prob * 2
                if extensible:
                    w.put(1 if use_ext else 0, 1)
                present = [self._present(e, deep) for e in root]
                for e, p in zip(root, present):
                    if e['opt']:
                        w.put(1 if p else 0, 1)
                for e, p in zip(root, present):
                    if p:
                        self._enc(e['func'], w)
                if use_ext:
                    n = len(adds)
                    w.put(0, 1); w.put(n - 1, 6)       # normally small length of the bitmap
                    pres = [rng.random() < 0.6 for _ in adds]
                    if not any(pres):
                        pres[0] = True
                    for p in pres:
                        w.put(1 if p else 0, 1)
                    for e, p in zip(adds, pres):
                        if p:
                            inner = Bits()
                            if not e['opt']:
                                pass
                            self._enc(e['func'], inner)
                            self.open_type(w, inner)
                return
            if t == 'choice':
                ents = self.tables[k[1]][1]
                extensible = any(e['ext'] != 'ASN1_NO_EXTENSIONS' for e in ents)
                root = [e for e in ents if e['ext'] != 'ASN1_NOT_EXTENSION_ROOT']
                adds = [e for e in ents if e['ext'] == 'ASN1_NOT_EXTENSION_ROOT']
                alts = root + ([] if deep else adds)
                if self.avoid_re and not deep and rng.random() < 0.95:
                    good = [e for e in alts if not re.search(self.avoid_re, e['hf'])]
                    if good and len(good) < len(alts):
                        # keep the numbering: pick among the good ones round robin
                        j = self.pick(k[1] + '#good', len(good))
                        i = alts.index(good[j])
                        alts = alts
                        return self._choice_enc(w, root, adds, alts, i, extensible)
                if deep:
                    i = min(range(len(root)), key=lambda j: self.score.get(root[j]['func'], 1))
                else:
                    i = self.pick(k[1], len(alts))
                return self._choice_enc(w, root, adds, alts, i, extensible)
            if t == 'seqof':
                ents = self.tables[k[1]][1]
                lo, hi, ext = k[2] or 0, k[3], k[4]
                n = max(lo, 1) if deep else rng.choice([1, 2, 3])
                if hi is not None:
                    n = min(n, hi)
                n = max(n, lo)
                if ext:
                    w.put(0, 1)
                self.length_det(w, n, lo, hi)
                for _ in range(n):
                    self._enc(ents[0]['func'], w)
                return
            if t == 'int':
                lo, hi, ext = k[1], k[2], k[3]
                if ext:
                    w.put(0, 1)
                if lo is None or hi is None:
                    raise ValueError('unconstrained integer')
                v = rng.choice([lo, hi, lo + (hi - lo) // 2, rng.randint(lo, min(hi, lo + 5000)),
                                rng.randint(max(lo, hi - 5000), hi), rng.randint(lo, hi)])
                if self.visit is not None:
                    self.visit.add(('int', func, 'lo' if v == lo else 'hi' if v == hi else v if hi - lo <= 300 else (v - lo) * 16 // (hi - lo + 1)))
                w.put(v - lo, nbits(hi - lo + 1))
                return
            if t == 'enum':
                root, ext = k[1], k[2]
                if ext:
                    w.put(0, 1)
                v = self.pick(func, root)
                if self.visit is not None:
                    self.visit.add(('enum', func, v))
                w.put(v, nbits(root))
                return
            if t == 'null':
                return
            if t == 'bool':
                w.put(rng.randrange(2), 1)
                return
            if t in ('bits', 'octets'):
                lo, hi, ext = k[1], k[2], k[3]
                unit = 1 if t == 'bits' else 8
                if ext:
                    w.put(0, 1)
                if func in self.fixed:
                    data = self.fixed[func](self) if callable(self.fixed[func]) else self.fixed[func]
                    n = len(data) if t == 'octets' else len(data) * 8
                    self.length_det(w, n, lo, hi)
                    for x in data:
                        w.put(x, 8)
                    return
                n = rng.choice([1, 2, 3, 4, 6, 9]) if t == 'octets' else rng.choice([1, 4, 8, 13, 24])
                if lo is not None and n < lo:
                    n = lo
                if hi is not None and n > hi:
                    n = hi
                self.length_det(w, n, lo, hi)
                if t == 'octets':
                    for _ in range(n):
                        w.put(rng.randrange(256), 8)
                else:
                    for _ in range(n):
                        w.put(rng.randrange(2), 1)
                return
            if t == 'str':
                bpc, alpha, lo, hi, ext = k[1], k[2], k[3], k[4], k[5]
                if ext:
                    w.put(0, 1)
                n = rng.choice([1, 3, 6, 10])
                if lo is not None and n < lo:
                    n = lo
                if hi is not None and n > hi:
                    n = hi
                self.length_det(w, n, lo, hi)
                if alpha:
                    al = sorted(alpha)
                    for _ in range(n):
                        w.put(rng.randrange(len(al)), bpc)
                else:
                    for _ in range(n):
                        w.put(rng.choice(b'abcdefghijklmnopABCDEFG0123'), 7)
                return
            # unknown: nothing
            return
        finally:
            self.depth -= 1


if __name__ == '__main__':
    import sys, collections
    s = PerSchema(sys.argv[1], sys.argv[2])
    print(collections.Counter(k[0] for k in s.funcs.values()))
    print([f for f, k in s.funcs.items() if k[0] == 'any'])
